def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n >= 99:
        return 'D'

    opp_last = history[-1][1]
    opp_d = sum(1 for _, o in history if o == 'D')
    my_d = sum(1 for m, _ in history if m == 'D')

    recent = history[-10:] if n >= 10 else history
    recent_opp_d = sum(1 for _, o in recent if o == 'D')
    rlen = len(recent)

    punished = 0
    forgiven = 0
    unprovoked = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_my == 'D':
            if cur_opp == 'D':
                punished += 1
            else:
                forgiven += 1
        else:
            if cur_opp == 'D':
                unprovoked += 1

    if opp_d > 0 and my_d > opp_d + 3:
        return 'C'

    if unprovoked >= 3 and unprovoked * 2 >= n:
        return 'D'

    if opp_d * 3 >= n and recent_opp_d >= max(2, rlen // 2):
        return 'D'

    if opp_d == 0 and n >= 85:
        return 'D'

    recent_forgiven = n >= 2 and history[-2][0] == 'D' and opp_last == 'C'
    if (
        n >= 80
        and recent_forgiven
        and forgiven >= 1
        and punished == 0
        and recent_opp_d <= 1
        and unprovoked <= 2
    ):
        if opp_d <= max(1, n // 10) and rng.random() < 0.6:
            return 'D'

    if opp_last == 'D':
        if history[-2][0] == 'C':
            if unprovoked <= 1 and recent_opp_d <= 1 and opp_d <= 2:
                return 'C' if rng.random() < 0.35 else 'D'
            return 'D'

        if opp_d * 3 < n * 2 and recent_opp_d <= max(2, (rlen * 3) // 5):
            return 'C' if rng.random() < 0.6 else 'D'

        if recent_opp_d <= 1:
            return 'C'

        return 'D'

    return 'C'
